@import "tailwindcss";

/* ============================================
   YODEV - Design System v3.0
   Dark-First Modern Agency Theme
   ============================================ */

:root {
  /* Spacing & Layout */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-2xl: 32px;
  --radius-3xl: 40px;
  --radius-full: 9999px;

  /* Grid & Container */
  --grid-size: 48px;
  --header-height: 72px;
  --container-max: 1280px;
  --section-gap: 100px;
  --section-gap-mobile: 60px;

  /* Typography */
  --font-body: var(--font-jakarta);
  --font-display: var(--font-dm-sans);
  --font-mono: var(--font-fira);

  /* Transitions */
  --transition-fast: 0.15s ease-out;
  --transition-base: 0.25s ease-in-out;
  --transition-slow: 0.4s ease-in-out;
  --transition-bounce: 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);

  /* Primary Colors */
  --primary: 27 168 150;           /* #1BA896 - Teal */
  --primary-light: 47 188 170;     /* Teal lighter */
  --primary-dark: 20 138 123;      /* Teal darker */
  --secondary: 255 107 53;         /* #FF6B35 - Orange */
  --secondary-light: 255 137 93;   /* Orange lighter */
  --secondary-dark: 225 77 23;     /* Orange darker */
}

/* ============================================
   THEME: DARK MODE (Default)
   ============================================ */
html[data-theme="dark"],
html:not([data-theme]) {
  --bg: 15 17 17;                  /* #0F1111 - Deep Charcoal */
  --bg-2: 20 22 22;                /* Slightly lighter */
  --surface: 31 33 33;             /* Card background */
  --surface-2: 42 44 44;           /* Elevated surface */
  --text: 255 251 248;             /* #FFFBF8 - Off-white */
  --text-muted: 156 163 175;       /* Gray-400 */
  --border: 255 255 255 / 0.08;
  --border-strong: 255 255 255 / 0.15;
  --ring: var(--primary) / 0.5;
  --shadow-color: 0 0 0;
  --gradient-start: 15 17 17;
  --gradient-end: 20 22 22;
  --glass-bg: 255 255 255 / 0.03;
  --glass-border: 255 255 255 / 0.08;
  color-scheme: dark;
}

/* ============================================
   THEME: LIGHT MODE
   ============================================ */
html[data-theme="light"] {
  --bg: 250 251 252;               /* #fafbfc */
  --bg-2: 244 246 248;             /* #f4f6f8 */
  --surface: 255 255 255;          /* #ffffff */
  --surface-2: 248 250 252;        /* #f8fafc */
  --text: 15 17 17;                /* Dark charcoal */
  --text-muted: 107 114 128;       /* Gray-500 */
  --border: 15 17 17 / 0.08;
  --border-strong: 15 17 17 / 0.15;
  --ring: var(--primary) / 0.4;
  --shadow-color: 15 17 17;
  --gradient-start: 250 251 252;
  --gradient-end: 244 246 248;
  --glass-bg: 255 255 255 / 0.7;
  --glass-border: 0 0 0 / 0.08;
  color-scheme: light;
}

/* ============================================
   SHADOWS
   ============================================ */
:root {
  --shadow-xs: 0 1px 2px rgb(var(--shadow-color) / 0.05);
  --shadow-sm: 0 2px 8px rgb(var(--shadow-color) / 0.08);
  --shadow-md: 0 8px 24px rgb(var(--shadow-color) / 0.12);
  --shadow-lg: 0 20px 48px rgb(var(--shadow-color) / 0.16);
  --shadow-xl: 0 32px 64px rgb(var(--shadow-color) / 0.20);
  --shadow-glass: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
  --shadow-glow: 0 0 0 1px rgb(var(--primary) / 0.2),
                 0 8px 32px rgb(var(--primary) / 0.15);
  --shadow-glow-hover: 0 0 0 1px rgb(var(--primary) / 0.3),
                       0 12px 40px rgb(var(--primary) / 0.25);
  --shadow-glow-secondary: 0 0 20px rgba(255, 107, 53, 0.3);
}

/* ============================================
   TAILWIND THEME INLINE
   ============================================ */
@theme inline {
  --color-bg: rgb(var(--bg));
  --color-bg-2: rgb(var(--bg-2));
  --color-surface: rgb(var(--surface));
  --color-surface-2: rgb(var(--surface-2));
  --color-text: rgb(var(--text));
  --color-muted: rgb(var(--text-muted));
  --color-border: rgb(var(--border));
  --color-border-strong: rgb(var(--border-strong));

  /* Primary colors */
  --color-primary: rgb(var(--primary));
  --color-primary-light: rgb(var(--primary-light));
  --color-primary-dark: rgb(var(--primary-dark));

  /* Secondary colors */
  --color-secondary: rgb(var(--secondary));
  --color-secondary-light: rgb(var(--secondary-light));
  --color-secondary-dark: rgb(var(--secondary-dark));

  /* Ring */
  --color-ring: rgb(var(--ring));

  /* Legacy aliases for compatibility */
  --color-accent: rgb(var(--primary));
  --color-accent-2: rgb(var(--primary-light));
  --color-dark: rgb(15 17 17);
  --color-card: rgb(var(--surface) / 0.6);

  /* Shadows */
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-glow: var(--shadow-glow);
  --shadow-glass: var(--shadow-glass);

  /* Border radius */
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-2xl: var(--radius-2xl);
  --radius-3xl: var(--radius-3xl);
  --radius-full: var(--radius-full);

  /* Fonts */
  --font-body: var(--font-body);
  --font-display: var(--font-display);
  --font-mono: var(--font-mono);
}

/* ============================================
   BASE STYLES
   ============================================ */
*,
::before,
::after {
  border-color: rgb(var(--border));
}

html {
  scroll-behavior: smooth;
}

body {
  background: rgb(var(--bg));
  color: rgb(var(--text));
  font-family: var(--font-body);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-display);
  letter-spacing: -0.02em;
  font-weight: 700;
}

::selection {
  background: rgb(var(--primary) / 0.3);
  color: rgb(var(--text));
}

/* Focus styles */
:focus-visible {
  outline: 2px solid rgb(var(--primary));
  outline-offset: 2px;
}

/* Summary/Details reset */
summary {
  list-style: none;
  cursor: pointer;
}

summary::-webkit-details-marker {
  display: none;
}

/* ============================================
   GLASS MORPHISM EFFECTS
   ============================================ */

/* Main glass panel - used across all pages */
.glass-panel {
  background: rgb(var(--glass-bg));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgb(var(--glass-border));
  box-shadow: var(--shadow-glass);
}

/* Glass panel with solid background - for headers/dropdowns */
.glass-panel-solid {
  background: #0f1111;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgb(var(--glass-border));
  box-shadow: var(--shadow-glass);
}

html[data-theme="light"] .glass-panel-solid {
  background: #fafbfc;
}

/* Glass with stronger blur */
.glass-panel-strong {
  background: rgb(255 255 255 / 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgb(255 255 255 / 0.1);
  box-shadow: var(--shadow-glass);
}

/* Glass for navigation when scrolled */
.glass-nav {
  background: rgb(var(--bg) / 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgb(var(--glass-border));
}

/* ============================================
   GRADIENT BACKGROUNDS
   ============================================ */

/* Mesh gradient - main page backgrounds */
.mesh-gradient {
  background:
    radial-gradient(at 0% 0%, rgba(27, 168, 150, 0.15) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(255, 107, 53, 0.1) 0px, transparent 50%),
    radial-gradient(at 50% 50%, rgb(var(--bg)) 0px, transparent 100%);
}

/* Mesh gradient subtle - for sections */
.mesh-gradient-subtle {
  background:
    radial-gradient(at 0% 0%, rgba(27, 168, 150, 0.08) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(255, 107, 53, 0.05) 0px, transparent 50%);
}

/* Hero glow effect */
.hero-glow {
  position: absolute;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(27, 168, 150, 0.2) 0%, transparent 70%);
  filter: blur(60px);
  z-index: -1;
  pointer-events: none;
}

.hero-glow-secondary {
  position: absolute;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(255, 107, 53, 0.15) 0%, transparent 70%);
  filter: blur(60px);
  z-index: -1;
  pointer-events: none;
}

/* ============================================
   TEXT EFFECTS
   ============================================ */

/* Gradient text - primary */
.text-gradient {
  background: linear-gradient(135deg, #FFF 0%, rgba(255,255,255,0.7) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Gradient text - primary colored */
.text-gradient-primary {
  background: linear-gradient(135deg, rgb(var(--primary)), rgb(var(--primary-light)));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Gradient text - secondary colored */
.text-gradient-secondary {
  background: linear-gradient(135deg, rgb(var(--secondary)), rgb(var(--secondary-light)));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ============================================
   DECORATIVE ELEMENTS
   ============================================ */

/* Security scan grid background */
.security-grid {
  background-size: 40px 40px;
  background-image: radial-gradient(circle, rgba(27, 168, 150, 0.1) 1px, transparent 1px);
}

/* Dots grid background */
.bg-grid-dots {
  background-image: radial-gradient(rgba(27, 168, 150, 0.15) 1px, transparent 1px);
  background-size: 30px 30px;
}

/* Lines grid background */
.bg-grid {
  background-image:
    linear-gradient(to right, rgb(var(--primary) / 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgb(var(--primary) / 0.04) 1px, transparent 1px);
  background-size: var(--grid-size) var(--grid-size);
}

/* Gradient orbs */
.orb {
  position: absolute;
  border-radius: var(--radius-full);
  filter: blur(60px);
  opacity: 0.5;
  pointer-events: none;
  background: radial-gradient(
    circle,
    rgb(var(--primary) / 0.4),
    transparent 70%
  );
}

.orb-secondary {
  background: radial-gradient(
    circle,
    rgb(var(--secondary) / 0.3),
    transparent 70%
  );
}

/* Code block styling */
.code-block {
  background: #0d1117;
  border-radius: 1rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-family: var(--font-mono);
}

.code-comparison-legacy {
  background: linear-gradient(135deg, rgba(255, 107, 53, 0.12), rgba(15, 17, 17, 0.7));
  border: 1px solid rgba(255, 107, 53, 0.25);
}

.code-comparison-modern {
  background: linear-gradient(135deg, rgba(27, 168, 150, 0.12), rgba(15, 17, 17, 0.7));
  border: 1px solid rgba(27, 168, 150, 0.25);
}

/* Hero code card - dark mode */
.hero-code-card {
  background: #0f1111;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

/* Hero code card - light mode */
html[data-theme="light"] .hero-code-card {
  background: #ffffff;
  border: 1px solid rgb(27 168 150 / 0.3);
  box-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.1);
}

html[data-theme="light"] .hero-code-card .text-primary {
  color: rgb(20 138 123);
}

html[data-theme="light"] .hero-code-card .text-white\/80 {
  color: rgb(31 41 55);
}

html[data-theme="light"] .hero-code-card .text-muted {
  color: rgb(107 114 128);
}

/* Hero status tag - light mode */
html[data-theme="light"] .hero-status-tag {
  background: #ffffff;
  border: 1px solid rgb(27 168 150 / 0.3);
  box-shadow: 0 10px 25px -5px rgb(0 0 0 / 0.1);
}

html[data-theme="light"] .hero-status-tag p {
  color: rgb(31 41 55);
}

/* Hero decorative background - light mode */
html[data-theme="light"] .hero-code-bg {
  background: #ffffff;
}

/* Metric cards with gradient border */
.metric-card {
  background: linear-gradient(145deg, rgba(27, 168, 150, 0.05), rgba(15, 17, 17, 0.5));
  border: 1px solid rgba(27, 168, 150, 0.15);
}

/* ROI card styling */
.roi-card {
  background: linear-gradient(145deg, rgba(27, 168, 150, 0.05) 0%, rgba(15, 17, 17, 0.8) 100%);
  border: 1px solid rgba(27, 168, 150, 0.15);
}

/* ============================================
   ANIMATIONS
   ============================================ */
@media (prefers-reduced-motion: no-preference) {
  /* Floating animation */
  .float {
    animation: float 3s ease-in-out infinite;
  }

  .animate-float {
    animation: float 6s ease-in-out infinite;
  }

  .float-slow {
    animation: float 8s ease-in-out infinite;
  }

  .float-slower {
    animation: float 12s ease-in-out infinite;
  }

  /* Fade up on load */
  .fade-up {
    animation: fade-up 0.6s ease-out both;
  }

  /* Pulse glow */
  .pulse-glow {
    animation: pulse-glow 2s ease-in-out infinite;
  }

  /* Pulse slow */
  .pulse-slow {
    animation: pulse 6s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  /* Scan line effect */
  .scan-line {
    animation: scan 2s linear infinite;
  }

  /* Spin slow */
  .spin-slow {
    animation: spin 12s linear infinite;
  }

  /* Shimmer effect for loading states */
  .shimmer {
    animation: shimmer 2s linear infinite;
    background: linear-gradient(
      90deg,
      rgb(var(--surface)) 0%,
      rgb(var(--surface-2)) 50%,
      rgb(var(--surface)) 100%
    );
    background-size: 200% 100%;
  }

  /* Line drawing animation */
  .line-draw {
    stroke-dasharray: 100;
    stroke-dashoffset: 100;
    animation: dash 3s linear infinite;
  }

  /* Glow animation */
  .animate-glow {
    animation: glow 4s ease-in-out infinite;
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse-glow {
  0%, 100% {
    box-shadow: 0 0 0 0 rgb(var(--primary) / 0.4);
  }
  50% {
    box-shadow: 0 0 20px 4px rgb(var(--primary) / 0.2);
  }
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes scan {
  0% {
    top: 0%;
  }
  100% {
    top: 100%;
  }
}

@keyframes dash {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes glow {
  0%, 100% {
    opacity: 0.3;
    transform: scale(1);
  }
  50% {
    opacity: 0.6;
    transform: scale(1.1);
  }
}

@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* ============================================
   UTILITY CLASSES
   ============================================ */

/* Card hover effect */
.card-hover {
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card-hover:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

/* Button glow effect */
.btn-glow {
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.btn-glow:hover {
  box-shadow: var(--shadow-glow-hover);
  transform: scale(1.02);
}

/* Button primary glow */
.btn-primary-glow:hover {
  box-shadow: 0 0 20px rgba(27, 168, 150, 0.3);
}

/* Button secondary glow */
.btn-secondary-glow:hover {
  box-shadow: var(--shadow-glow-secondary);
}

/* Link underline animation */
.link-underline {
  position: relative;
}

.link-underline::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: rgb(var(--primary));
  transition: width var(--transition-base);
}

.link-underline:hover::after {
  width: 100%;
}

/* Border animations */
.border-glow {
  position: relative;
}

.border-glow::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, rgb(var(--primary)), rgb(var(--secondary)));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.border-glow:hover::before {
  opacity: 1;
}

/* No scrollbar utility */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgb(var(--bg-2));
}

::-webkit-scrollbar-thumb {
  background: rgb(var(--text-muted) / 0.3);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background: rgb(var(--text-muted) / 0.5);
}

/* ============================================
   FORM ELEMENTS
   ============================================ */

/* Custom range slider */
input[type="range"] {
  -webkit-appearance: none;
  background: rgba(255, 255, 255, 0.1);
  height: 6px;
  border-radius: 3px;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  height: 18px;
  width: 18px;
  background: rgb(var(--primary));
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 0 10px rgba(27, 168, 150, 0.5);
  transition: transform var(--transition-fast);
}

input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.1);
}

input[type="range"]::-moz-range-thumb {
  height: 18px;
  width: 18px;
  background: rgb(var(--primary));
  border-radius: 50%;
  cursor: pointer;
  border: none;
  box-shadow: 0 0 10px rgba(27, 168, 150, 0.5);
}

/* Custom checkbox */
input[type="checkbox"] {
  appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid rgb(var(--border-strong));
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
}

input[type="checkbox"]:checked {
  background: rgb(var(--primary));
  border-color: rgb(var(--primary));
}

input[type="checkbox"]:checked::after {
  content: '✓';
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgb(var(--bg));
  font-size: 12px;
  font-weight: bold;
}

/* ============================================
   RESPONSIVE UTILITIES
   ============================================ */
@media (max-width: 768px) {
  :root {
    --section-gap: var(--section-gap-mobile);
    --grid-size: 32px;
  }

  .hero-glow,
  .hero-glow-secondary {
    width: 300px;
    height: 300px;
  }
}

/* ============================================
   ALPINE.JS COMPATIBILITY (for transition)
   ============================================ */
[x-cloak] {
  display: none !important;
}

